  const N=GPS_ELLIPSOID&&c.altitude!=null? geoidN(c.latitude,c.longitude) : null; st.geoidN=N;
  st.alt = c.altitude!=null? (c.altitude-(N||0))*3.28084 : null;   // ellipsoid -> EGM96 (~MSL), the datum of SRTM and the AIP
  $('sAltBox').title=N==null? 'GPS altitude'+(GPS_ELLIPSOID?' (no geoid correction outside Australia)':'') : `GPS altitude above mean sea level: the phone's WGS84 ellipsoid height ${N>=0?'minus':'plus'} the EGM96 geoid height here (${Math.abs(N).toFixed(0)} m, ${Math.round(Math.abs(N)*3.28084)} ft)`;
  st.gs = c.speed!=null? c.speed*1.943844 : st.gs;
